import {
  getLocalSolvedPuzzleMap,
  PuzzleInfoBox,
  ClickableMonarchDevice,
} from "@hunt/puzzle-components";
import React from "react";

const CAPSTONE_SLUG = "lights_down_mode";

export default function PuzzleComponent() {
  const solvedPuzzles = getLocalSolvedPuzzleMap();

  return CAPSTONE_SLUG in solvedPuzzles ? (
    <div className="flex items-center gap-2">
      The Brights Puzzmon need your help lighting up Wattissimo. Can you guide
      them to the right spots?
      <ClickableMonarchDevice zoneSlug="the_brights" className="w-20" />,
    </div>
  ) : (
    <PuzzleInfoBox copyable={false}>
      You need to solve the{" "}
      <a href={`/puzzles/${CAPSTONE_SLUG}`}>The Brights capstone puzzle</a>{" "}
      before you can access this task.
    </PuzzleInfoBox>
  );
}
